-- 0000_baseline.sql
-- Full current schema of the public schema, generated by introspecting
-- the live Supabase database. Fully idempotent (safe to run against the
-- existing production DB, where every statement is a no-op, or against a
-- fresh Supabase project to recreate the schema from empty).
--
-- Authorization is enforced in the app layer (no RLS). The cross-schema FK
-- from user_profiles.id -> auth.users(id) requires Supabase's auth schema
-- to exist (it does on any Supabase project).

-- ============ Tables ============
CREATE TABLE IF NOT EXISTS ad_creatives (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  campaign_id text NOT NULL,
  platform text NOT NULL,
  ad_id text NOT NULL,
  ad_name text NOT NULL,
  creative_type text NOT NULL,
  headline text NOT NULL,
  body_copy text NOT NULL,
  thumbnail_url text NOT NULL,
  impressions bigint DEFAULT 0 NOT NULL,
  clicks bigint DEFAULT 0 NOT NULL,
  spend numeric(12,2) DEFAULT 0 NOT NULL,
  conversions bigint DEFAULT 0 NOT NULL,
  ctr numeric(8,4) DEFAULT 0 NOT NULL,
  cpc numeric(10,4) DEFAULT 0 NOT NULL,
  cpa numeric(10,2) DEFAULT 0 NOT NULL,
  first_served date NOT NULL,
  last_served date NOT NULL,
  days_running integer DEFAULT 0 NOT NULL,
  status text DEFAULT 'active'::text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS alert_history (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  rule_id uuid NOT NULL,
  client_id uuid NOT NULL,
  triggered_at timestamp with time zone DEFAULT now() NOT NULL,
  metric text NOT NULL,
  actual_value numeric NOT NULL,
  threshold_value numeric NOT NULL,
  severity text DEFAULT 'warning'::text NOT NULL,
  status text DEFAULT 'triggered'::text NOT NULL,
  resolved_at timestamp with time zone,
  notification_sent boolean DEFAULT true NOT NULL,
  rule_name text,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS alert_rules (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  name text NOT NULL,
  metric text NOT NULL,
  condition text NOT NULL,
  threshold numeric NOT NULL,
  evaluation_window text DEFAULT 'daily'::text NOT NULL,
  platform text,
  campaign_id text,
  enabled boolean DEFAULT true NOT NULL,
  recipients text[] DEFAULT '{}'::text[] NOT NULL,
  frequency text DEFAULT 'realtime'::text NOT NULL,
  severity text DEFAULT 'warning'::text NOT NULL,
  quiet_hours_enabled boolean DEFAULT false NOT NULL,
  quiet_hours_start text,
  quiet_hours_end text,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS attribution_journeys (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  conversion_date date NOT NULL,
  revenue numeric(12,2) DEFAULT 0 NOT NULL,
  path text[] DEFAULT '{}'::text[] NOT NULL,
  converting_platform text NOT NULL,
  touch_count integer DEFAULT 1 NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS campaign_budgets (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  campaign_id text NOT NULL,
  monthly_budget numeric(12,2) NOT NULL,
  month text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS campaign_performance (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  platform text NOT NULL,
  campaign_id text NOT NULL,
  campaign_name text NOT NULL,
  date date NOT NULL,
  impressions integer DEFAULT 0 NOT NULL,
  clicks integer DEFAULT 0 NOT NULL,
  spend numeric(12,2) DEFAULT 0 NOT NULL,
  conversions integer DEFAULT 0 NOT NULL,
  ctr numeric(8,4) DEFAULT 0 NOT NULL,
  cpc numeric(10,4) DEFAULT 0 NOT NULL,
  cpm numeric(10,4) DEFAULT 0 NOT NULL,
  raw_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  revenue numeric(14,2) DEFAULT 0 NOT NULL
);

CREATE TABLE IF NOT EXISTS chat_messages (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  session_id uuid NOT NULL,
  role text NOT NULL,
  content text NOT NULL,
  reference_context jsonb,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS chat_sessions (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  title text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS client_members (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  user_id uuid NOT NULL,
  client_id uuid NOT NULL,
  role text DEFAULT 'viewer'::text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS clients (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  name text NOT NULL,
  industry text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS customer_cohorts (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  acquisition_platform text NOT NULL,
  cohort_month text NOT NULL,
  customers integer DEFAULT 0 NOT NULL,
  acquisition_spend numeric(14,2) DEFAULT 0 NOT NULL,
  retention jsonb DEFAULT '[]'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS dashboards (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  name text DEFAULT 'Default'::text NOT NULL,
  is_default boolean DEFAULT true NOT NULL,
  layouts jsonb DEFAULT '{"lg": [], "md": [], "sm": []}'::jsonb NOT NULL,
  widgets jsonb DEFAULT '[]'::jsonb NOT NULL,
  version integer DEFAULT 1 NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS report_schedules (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  name text NOT NULL,
  frequency text NOT NULL,
  day_of_week integer,
  day_of_month integer,
  time_of_day text DEFAULT '09:00'::text NOT NULL,
  date_range_type text DEFAULT 'last_30'::text NOT NULL,
  custom_days integer,
  include_comparison boolean DEFAULT true NOT NULL,
  recipients text[] DEFAULT '{}'::text[] NOT NULL,
  subject_template text DEFAULT '{{clientName}} Performance Report'::text NOT NULL,
  message_template text DEFAULT ''::text NOT NULL,
  require_approval boolean DEFAULT false NOT NULL,
  enabled boolean DEFAULT true NOT NULL,
  last_sent_at timestamp with time zone,
  next_send_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS reports (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  client_id uuid NOT NULL,
  title text NOT NULL,
  date_range_start date NOT NULL,
  date_range_end date NOT NULL,
  comparison_start date NOT NULL,
  comparison_end date NOT NULL,
  narrative text DEFAULT ''::text NOT NULL,
  metrics_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  share_token text,
  share_password_hash text,
  share_expires_at timestamp with time zone
);

CREATE TABLE IF NOT EXISTS user_profiles (
  id uuid NOT NULL,
  full_name text,
  role text DEFAULT 'client_user'::text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

