  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'reports_client_id_fkey' AND conrelid = 'public.reports'::regclass
  ) THEN
    ALTER TABLE reports ADD CONSTRAINT reports_client_id_fkey FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE;
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'user_profiles_id_fkey' AND conrelid = 'public.user_profiles'::regclass
  ) THEN
    ALTER TABLE user_profiles ADD CONSTRAINT user_profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
  END IF;
END $$;

